ace=c('bold'),   vjust 	= -4, size = 20),  		axis.title.y = element_text(colour = "black", family="Times", angle=90, 	face=c('bold'), vjust= 5, size = 20),            panel.grid.minor = element_blank(),            panel.grid.major = element_blank(),            plot.background = element_rect(fill="white", color = "white"),	panel.border = element_blank(),	panel.background = element_blank(),	plot.margin=unit(c(1,1.5,1.3,1.3),"cm")    )   }theme_set(theme_jack())## The following gives a modified ggplot function - adds 10% to y-axis. MUST define xxx and yyy in loop before using ggplotFB:ggplotFB <- function(...) ggplot2:::ggplot(...)  + {if (all(xxx >= 0, na.rm = TRUE)) scale_x_continuous(expand = c(0, 0), limits = c(0, NA))} + {if (all(yyy >= 0, na.rm = TRUE)) scale_y_continuous(expand = c(0, 0), limits = c(0, NA))} + {if ((all(xxx >= 0, na.rm = TRUE)) & (all(yyy >= 0, na.rm = TRUE))) coord_cartesian(xlim = c(0, max(xxx, na.rm = TRUE)), ylim = c(0, max(yyy, na.rm = TRUE) + max(yyy, na.rm = TRUE)/10))}  integer_breaks <- function(n = 5, ...) {    fxn <- function(x) {        breaks <- floor(pretty(x, n, ...))        names(breaks) <- attr(breaks, "labels")        breaks    }    return(fxn)}int_breaks_drop_zero <- function(n = 5, ...) { ## use -breaks=int_breaks_drop_zero(n = 7))   fxn <- function(x) {    breaks <- floor(pretty(x, n, min.n = 0, ...))    breaks <- breaks[breaks != 0]    if (length(breaks) == 0) return(NULL)    names(breaks) <- attr(pretty(x, n, min.n = 0, ...), "labels")    breaks  }  return(fxn)}##________________________________________________________## Section 1A. Figures 0A and 0B. Variable construct. Data chosen for aesthetic reasons.set.seed(567)I <- c(13, rep(22, 3), rep(40, 4), rep(55.5, 2), 19.0, 39.5, 35.7, 60, 70)x1 <- rep("I", length(I))II <- c(20, rep(40, 2), rep(50, 3), rep(60, 3), rnorm(5, 80, 15), rep(80, 4), rep(90, 3), 100)x2 <- rep("II", length(II))df1 <- data.frame(x1, I)colnames(df1) <- c("x", "