A else omnibus_p(y) < alpha  })  mean(hits, na.rm = TRUE)}minimum_bump <- function(m, r, loc, target = 0.90, by = 0.25, grid = seq(1.5, 10, by = by)) {  for (B in grid) if (sim_power(m, r, loc, B, R = R) >= target) return(B)  NA}set.seed(123)nn <- 1:4 		## number of replicates assessedm <- 90      	## design assumption: 90 articles use n = 1:4r <- 0.6     		## assumed local decay stepR <- 100000 	## number of simulationsby <- 0.25		## precision### aaa <- Sys.time()### bumprange <- c(1.5, 2, 2.5, 3, 4) ## multiple of log-linear fit point### for (B in bumprange) {### if (B == bumprange[[1]]) {  ### cat(sprintf("Omnibus power (bump only), m = %d, r = %.1f, by = %.2f, alpha = 0.05\n", m, r, by))### cat(sprintf("%-6s %-9s %-9s %-9s %-9s\n", "B", "n=1", "n=2", "n=3", "n=4"))### }###   cat(sprintf("%-6.2f %-9.3f %-9.3f %-9.3f %-9.3f\n", B,###       sim_power(m, r, 1, B, R=R), sim_power(m, r, 2, B, R=R),###       sim_power(m, r, 3, B, R=R), sim_power(m, r, 4, B, R=R)))### }### bbb <- Sys.time()### bbb - aaa### ## Time difference of 24.52515 mins## TABLE S7.T1 (from loop above). Omnibus power (for one bump at either replicate number 1,2,3, or 4 - given as n below), m = 90, r = 0.6, alpha = 0.05.## column definitions:## B = bump = multiple of log-linear fit point.## n = replicate number. ## B      n=1       n=2       n=3       n=4      ## 1.50   0.053     0.670     0.324     0.070    ## 2.00   0.059     0.956     0.677     0.133    ## 2.50   0.082     0.997     0.896     0.280    ## 3.00   0.108     1.000     0.974     0.467    ## 4.00   0.162     1.000     0.999     0.778 ## minimum detectable bump per location, for settings above (except n>1 by=0.1):### ccc <- Sys.time()### for (loc in nn) {### if (loc == nn[[1]]) {### by <- 0.25### cat(paste0("\nMinimum detectable bump (>=90% power): precision by = ", by, "\n"))###   v <- minimum_bump(m, r, loc, by = by) ## n=1 tested with by = 0.25 ### } else {### by <- 0.1### cat(paste0("\nMinimum detectable bump (>=90% power): precision by = ", by, "\n"))###   v <- minimum_bump(m, r, loc, by = by) ## others tested with by = 0.1 ### }###   cat(sprintf("  bump at n=%d : %s\n", loc,###       if (is.na(v)) ">10x (effectively undetectable)" else sprintf("%.2fx", v)))### }### ddd <- Sys.time()### ddd - ccc### ### ## Time difference of 1.74674 hours## Minimum detectable bump (>=90% power): precision by = 0.25##   bump at n=1 : >10x (effectively undetectable)## Minimum detectable bump (>=90% power): precision by = 0.1##   bump at n=2 : 1.90x## Minimum detectable bump (>=90% power): precision by = 0.1##   bump at n=3 : 2.60x## Minimum detectable bump (>=90% power): precision by = 0.1##   bump at n=4 : 4.80x## Sensitivity to r - assumed baseline slope:r_values <- c(0.4, 0.5, 0.6, 0.7, 0.8)### ggg <- Sys.time()### for (rr in r_values) {### if (rr == r_values[[1]]) {### cat(paste0("\nSensitivity: minimum detectable bump (>=90% power):\n"))### cat(sprintf("%-6s %-8s %-8s %-8s %-8s\n", "r", "n=1", "n=2", "n=3", "n=4"))### }###   cat(sprintf("%-6.1f", rr))###   for (loc in 1:4) {### if (loc == 1) {### by <- 0.25###   v <- minimum_bump(m, rr, loc, by = by)###     cat(sprintf("%-8s", if (is.na(v)) ">10x" else sprintf("%.2fx", v)))### } else {### by <- 0.1###   v <- minimum_bump(m, rr, loc, by = by)###     cat(sprintf("%-8s", if (is.na(v)) ">10x" else sprintf("%.2fx", v)))###   }### }###   cat("\n")### }### hhh <- Sys.time()### hhh - ggg### ## Time difference of 9.182625 hours## TABLE S7.T2 (from loop above). Sensitivity of minimum detectable bump to changes in r (= assumed baseline slope) (>=90% power).## n=2 and n=3 are only slightly r-insensitive; n=4 is strongly r-dependent; n=1 is undetectable at any r.## column definitions:## r = assumed baseline slope.## n = replicate number. ## r      n=1      n=2      n=3      n=4     ## 0.4   >10x    1.80x   3.20x   7.60x   ## 0.5   >10x    1.80x   2.80x   5.80x   ## 0.6   >10x    1.90x   2.60x   4.80x   ## 0.7   >10x    1.90x   2.40x   4.10x   ## 0.8   >10x    2.00x   2.40x   3.70x ## Section 2. Collated batch replication results. This collects data from the .csv file_S9 column "conclusion". The data are the results from the protocol categorizations and are shown below. The graph produced in this section groups the protocols into NoR, G2, D, G3 and T. collated <- fread(paste0(mypath, "S9_Supplemental_File_S9_Collated.csv"), header = TRUE)collated <- as.data.frame(collated)conclusion <- collated$conclusioncollated$exact_methods <- as.numeric(collated$exact_methods)nrow(collated)collated$con2 <- collated$conclusiontableconclusion <- table(conclusion)tableconclusion <- as.data.frame(tableconclusion)tableconclusion## TABLE S7.T3 (tableconclusion). Collated data from file_S9 column "conclusion".## column definitions:## Var1 = name of protocol.## Freq = Frequency found in Protocol Report.##                                    Var1 Freq## 1   Double result (repetition) protocol   15## 2  Global (duplicated-methods) protocol    7## 3 Global (triplicated-methods) protocol   31## 4            Non-repeated (N3) protocol    7## 5 Non-repeated (single-result) protocol   23## 6   Triple result (repetition) protocol   17ArticleTotal <- sum(tableconclusion$Freq)ArticleTotal## 100df <- as.data.frame(table(collated$con2))dfdf$group <- c("D", "G2", "G3", "N3", "NoR", "T")neworder <- c("NoR", "N3", "G2", "D", "G3", "T")df <- df %>% slice(match(neworder, group))colnames(df) <- c("Var1", "Frequency", "group")dfdf$Proportion <- df$Frequency / ArticleTotaldf$Percentage <- paste0(round(df$Proportion * 100, digits = 0), "%")df$Percentage <- factor(df$Percentage, levels = unique(df$Percentage))df$group <- factor(df$group, levels = c("N3", "NoR", "G2", "D", "G3", "T")) ## prevents alphabetical ordering by ggplot !df$Protocol <- c("NoR", "NoR", "G2", "D", "G3+", "T+")df$Protocol <- factor(df$Protocol, levels = un