ntage group## N3        N3         7       0.07         7%   NoR## NoR      NoR        23       0.23        23%   NoR## G2        G2         7       0.07         7%    G2## D          D        15       0.15        15%     D## G3        G3        14       0.14        14%    G3## T          T        11       0.11        11%     T## G4        G4         3       0.03         3%    G4## T4        T4         2       0.02         2%    T4## G5        G5         2       0.02         2%    G5## T5        T5         1       0.01         1%    T5## G6+      G6+        12       0.12        12%   G6+## T6+      T6+         3       0.03         3%   T6+##________________________________________________________dfnumcodefreqprop <- dfnumcode[ , c("Frequency", "Proportion")]dfnumcodefreqprop ## Section 3. Batch replication - comparison with fitted models. ## Section 3A. Power law - using all exact_methods data.table_exact_methods2 <- table(collated$exact_methods) ## gives one-D matrixtable_exact_methods <- rbind(rownames(table_exact_methods2), table_exact_methods2) table_exact_methods <- as.data.frame.matrix(table_exact_methods)rownames(table_exact_methods) <- c("n", "f")colnames(table_exact_methods) <- NULL## TABLE S7.T6 (table_exact_methods). Numbers of replicates found in all studies with any number of replicates (i.e., not grouped into, e.g., 6+), with global and result replicates treated together.## row definitions:## n = number of replicates.## f = frequency of studies with that number of replicates.## n  1  2  3 4 5 6 8 9 10 16 22 52 59## f 30 22 25 5 3 4 2 1  3  1  1  1  2## Poisson generalized linear model fit with a log link (for a power law decay for count data): power-law fit: f = A*n^B  via Poisson GLM with log link: log(E[f]) = a + b*log(n) where A = exp(a),  B = b. The baseline for statistical testing excludes n=3 (but keeping n=3 datapoint makes little difference):n <- as.numeric(as.vector(unlist(table_exact_methods["n", ]))) f <- as.numeric(as.vector(unlist(table_exact_methods["f", ]))) ## Fits including/excluding n=3 datapoint:fit_excl <- glm(f ~ log(n), family = poisson(link = "log"), subset = (n != 3))A_excl <- exp(coef(fit_excl)[1]); B_excl <- coef(fit_excl)[2]fit_all <- glm(f ~ log(n), family = poisson(link = "log"))A_all <- exp(coef(fit_all)[1]); B_all <- coef(fit_all)[2]cat(sprintf("Baseline (excl. n=3):  f = %.2f * n^(%.3f)\n", A_excl, B_excl))## Baseline (excl. n=3):  f = 31.72 * n^(-1.102) ## also used in quasi-Poisson F-test cat(sprintf("Full dataset:          f = %.2f * n^(%.3f)\n\n", A_all, B_all))## Full dataset:          f = 36.24 * n^(-1.063)## Significance test: Likelihood-ratio test (LRT) with indicator for n = 3:d3 <- as.integer(n == 3)m0 <- glm(f ~ log(n), family = poisson(link = "log"))      # smooth decay (null)m1 <- glm(f ~ log(n) + d3,  family = poisson(link = "log"))      # adjusts for triplicate bumplrt <- anova(m0, m1, test = "LRT")excess <- exp(coef(m1)["d3"])                      # multiplicative excess at n=3excess##       d3 ## 2.645213 cat(sprintf("excess at n=3 = %.2f x trend;  chi2(1) = %.2f;  p = %.2e\n\n",            excess, lrt$Deviance[2], lrt$`Pr(>Chi)`[2]))## LRT (Poisson): does the n=3 term lie significantly above/below the fit ?:## excess at n=3 = 2.65 x trend;  chi2(1) = 14.71;  p = 1.25e-04## Section 3B. quasi-Poisson (F test); robust to mild overdispersion = main result:d3 <- as.integer(n == 3)mq0 <- glm(f ~ log(n),      family = quasipoisson(link = "log"))mq1 <- glm(f ~ log(n) + d3, family = quasipoisson(link = "log"))fq <- anova(mq0, mq1, test = "F")fq## Analysis of Deviance Table## Model 1: f ~ log(n)## Model 2: f ~ log(n) + d3##   Resid. Df Resid. Dev Df Deviance      F  Pr(>F)  ## 1        11     26.346                             ## 2        10     11.631  1   14.714 9.4212 0.01185 *## Signif. codes:  0 ‘***’ 0.001 ‘**’ 0.01 ‘*’ 0.05 ‘.’ 0.1 ‘ ’ 1excess <- exp(coef(mq1)["d3"])                      excess## 2.645213 ## d3 multiplicative excess at n=3exp(confint(mq1)["d3", ]) ## 95% confidence interval of excess:##    2.5 %   97.5 % ## 1.451795 4.576464 exp(coef(mq0)["(Intercept)"]) ## intercepts for mq0 and mq1 are similar##  36.23581exp(coef(mq1)["(Intercept)"])##   31.71932 phi <- summary(mq1)$dispersionphi## 1.561841 ## phi < 5 is not extreme overdispersion se <- summary(mq1)$coefficients["d3", "Std. Error"] se## 0.2907129dfres <- mq1$df.residual ## residual degrees of freedomdfres## 10tcrit <- qt(0.975, dfres) ## critical t valuetcrit## 2.228139## Wald t:summary(mq1)$coefficients["d3", "t value"] ## 3.346091## p-value## the p-value of 0.012 (quasi-Poisson ANOVA F-test) is chosen over 0.007 (Wald test from summary(mq1)) - to remain conservative.## Partial deviance D-squared:(deviance(mq0) - deviance(mq1)) / deviance(mq0)## 0.5585196## diagnostic plot - log-loggrid  <- seq(1, 59, length.out = 200)ngrid <- A_excl * grid^B_excl                      # fitted baseline curvepdf(paste0(mypath, "replicates_exact_methods.pdf"), width = 7, height = 5)    par(mar = c(4.5, 4.5, 2, 1))plot(n[!(n == 3)], f[!(n == 3)], log = "xy", pch = 19, col = "#378ADD", cex = 1.3, xlim = c(0.9, 70), ylim = c(0.8, 40), xlab = "Number of replicates (log scale)", ylab = "Frequency (log scale)",main = "Replicate-count frequency vs power-law decay")lines(grid, ngrid, col = "grey45", lwd = 2, lty = 2)            points(n[(n == 3)], f[(n == 3)], pch = 18, col = "#D85A30", cex = 2.2)    text(3, 25, labels = sprintf("  n=3: %.1fx trend\n  p = %.1e", excess, fq$`Pr(>F)`[2]),     pos = 4, col = "#D85A30", cex = 0.85)legend("topright", bty = "n", cex = 0.9,       legend = c(sprintf("Power-law null: %.1f \u00b7 n^%.2f", A_excl, B_excl),                  "Observed", "Triplicate (n=3)"),       col = c("grey45", "#378ADD", "#D85A30"),       lty = c(2, NA, NA), pch = c(NA, 19, 18), lwd = c(2, NA, NA))dev.off()## sprintf: %. gives the parameter number given after a comma in sprintf. The letter f,d,e,g,s gives the type: f fixed-point decimal, d integer, e scientific notation, g "pick whichever is shorter," s a string. The .N before the letter sets decimal places (for f/e/g). A number before the dot sets a minimum width for alignment — e.g. %8.2f pads to 8 characters wide. %% prints a literal percent sign.## Figure S7.A. Exact_methods data. Log-log plot of frequency of numbers of replicates versus numbers of replicates; showing that method triplication is statistically significantly increased above that expected from the power law null (fitted to all data minus n=3). The p-value is from a quasi-Poisson F test. (The n = 3 point is also significantly different from the power law fitted to all data - not shown as this is not generally performed.)## =============================================================## Section 4A. Quasi-Poisson scan of first four points, with Benjamini-Hochberg False Discovery Rate. Note that main comparison is between non-replicated, duplicated, triplicated and quadruplicated. If the approach using all 13 points is chosen the result does not survive corrections for multiple testing - but we are not interested in most of these points (!). Also, it could be argued that the excess (~2.6x) at n=3 mostly causes the increase in phi to ~3 for the other points (without n=3, phi is around 1.56). So the quasi-Poisson at n = 3 measures the excess against a dispersion the excess itself inflates - which is therefore ultra-conservative.myrange <- 1:4loo4A <- data.frame(n = n[myrange], observed = f[myrange], ratio = NA_real_, phi = NA_real_, F = NA_real_, p_raw = NA_real_)for (i in seq_along(n[myrange])) {dd <- as.integer(n == n[i])mq0 <- glm(f ~ log(n),      family = quasipoisson(link = "log"))mq1 <- glm(f ~ log(n) + dd, family = quasipoisson(link = "log"))fq <- anova(mq0, mq1, test = "F")excess <- exp(coef(mq1)["dd"])                        phi <- summary(mq1)$dispersion  p_value <- fq$"Pr(>F)"[2]loo4A$ratio[i] <- excess; loo4A$phi[i] <- phi; loo4A$F[i] <- fq$F[2]  loo4A$p_raw[i] <- p_value   }loo4A$p_BH   <- p.adjust(loo4A$p_raw, method = "BH")     # Benjamini-Hochberg FDRloo4A$p_bonf <- p.adjust(loo4A$p_raw, method = "bonferroni")  loo4A## TABLE S7.T7 (loo4A). Quasi-Poisson scan of first four replicate points, with Benjamini-Hochberg False Discovery Rate, assessing actual differences between frequencies of numbers of studies observed with either no replication or batch replication from 2 to 4 replicates.## column definitions:## n = number of replicates.## observed = number of studies with those number of replicates.## ratio = multiplicative difference (excess) between observed and expected.## phi = dispersion parameter.## F = F from F-test## p_raw = raw p-value## p_BH = p-value adjusted using Benjamini-Hochberg False Discovery Rate.## p_bonf = p-value adjusted using Bonferroni correction.## myrange <- 1:4##   n observed     ratio      phi         F      p_raw       p_BH     p_bonf## 1 1       30 0.5038120 3.121679 1.3697679 0.26898746 0.51106172 1.00000000## 2 2       22 1.3509571 3.102170 0.4643684 0.51106172 0.51106172 1.00000000## 3 3       25 2.6452130 1.561841 9.4212468 0.01185284 0.04741136 0.04741136## 4 4        5 0.5755452 2.823612 0.5968242 0.45766249 0.51106172 1.00000000## Section 4B. Leave-one-out scan of all points, with Benjamini-Hochberg False Discovery Rate. For each target point, a quasi-poisson decay to the other points was fitted, a fitted value for the point was predicted from the curve, and a studentised residual was created which accounted for overdispersion (phi) and the variance of the prediction itself. This was then tested using a t-distribution and corrected for multiple testing.dat <- data.frame(n = n, f = f)loo4B <- data.frame(n = n, observed = f, predicted = NA_real_, ratio = NA_real_, phi = NA_real_, z = NA_real_, p_raw = NA_real_)for (i in seq_along(n)) {  m   <- glm(f ~ log(n), family = quasipoisson(link = "log"), data = dat[-i, ])  pr  <- predict(m, newdata = dat[i, ], type = "link", se.fit = TRUE)  mu  <- exp(pr$fit)                      # leave-one-out prediction (count scale)  phi <- summary(m)$dispersion            # overdispersion estimated from the others  var_obs  <- phi * mu                    # quasi-Poisson variance of the observation  var_pred <- (mu * pr$se.fit)^2          # delta-method variance of the prediction  z <- (f[i] - mu) / sqrt(var_obs + var_pred)        # studentised deleted residual  loo4B$predicted[i] <- mu; loo4B$ratio[i] <- f[i] / mu; loo4B$phi[i] <- phi  loo4B$z[i] <- z  loo4B$p_raw[i] <- 2 * pt(-abs(z), df = m$df.residual)   # two-sided, t reference}loo4B$p_BH   <- p.adjust(loo4B$p_raw, method = "BH")          # Benjamini-Hochberg FDRloo4B$p_bonf <- p.adjust(loo4B$p_raw, method = "bonferroni")  # stricter, family-wiseloo4B## TABLE S7.T8 (loo4B). Leave-one-out scan of all 13 replicate points, with Benjamini-Hochberg False Discovery Rate, assessing actual differences between frequencies of numbers of studies observed with either no replication or batch replication from 2 to 13 replicates.## column definitions:## n = number of replicates (points).## observed = actual number of studies with those number of replicates.## predicted = number of studies predicted from quasi-poisson decay of other points.## ratio = multiplicative difference (excess) between observed and expected.## phi = dispersion parameter.## z = studentised deleted residual.## p_raw = raw p-value## p_BH = p-value adjusted using Benjamini-Hochberg False Discovery Rate.## p_bonf = p-value adjusted using Bonferroni correction.##     n observed  predicted     ratio      phi           z       p_raw       p_BH     p_bonf## 1   1       30 59.5460210 0.5038120 3.121679 -0.91762311 0.380415408 0.85710491 1.00000000## 2   2       22 16.2847509 1.3509571 3.102170  0.72550634 0.484773552 0.85710491 1.00000000## 3   3       25  9.45