e", "none", "stripe", "none", "stripe", "none", "stripe", "none", "stripe", "none")names(myPattern) <- dfnumcode$Protocol  myAngle <- c(135, 45, 45, 45, 45, 45, 45, 45, 45, 45, 45, 45)names(myAngle) <- dfnumcode$Protocol  legend_groups <- c("N3", "G3", "D")myLabels <- c("N3", "Global", "Result reps")legendPattern <- c("stripe", "stripe", "none")names(legendPattern) <- legend_groups legendAngle <- c(0, 45, 45)names(legendAngle) <- legend_groups legendColor <- c("#d3d3d3", "#d3d3d3", "#d3d3d3")names(legendColor) <- legend_groups myVjust <- c(3, 4, 3, 6, 6, 3, 1.5, 1.2, -2, -2, 2, 1.5) names(myVjust) <- dfnumcode$Protocol annotation1 <- data.frame(label = c("*"), x = c(3), y = c(0.27)) plotProtocolnumcode <- ggplot(data = dfnumcode, aes(x = group2, y = Proportion, fill = Protocol,  pattern = Protocol)) +geom_bar_pattern(stat = "identity", position = "stack", color = "black", pattern_fill = "black", pattern_color = cbp2B, pattern_angle = myAngle, pattern = myPattern) + scale_pattern_manual(values = myPattern, breaks = legend_groups) + scale_fill_manual(values = cbp2B, breaks = legend_groups, labels = myLabels) + guides(    fill = guide_legend(override.aes = list(fill = NA, pattern = legendPattern[legend_groups],                                            pattern_angle = myAngle[legend_groups],                                            pattern_color = "#d3d3d3")),    pattern = guide_legend(override.aes = list(pattern = legendPattern[legend_groups],                                               pattern_angle = myAngle[legend_groups],                                               pattern_color = "#d3d3d3"))) + labs(fill = "") +  theme(legend.key = element_rect(fill = "#d3d3d3")) + xlab("Protocol group") + geom_text(aes(label = Percentage), position = position_stack(), vjust =myVjust, color=c("black", "black", "white", "white", "white", "white", "white", "white", "black", "black", "white", "white"), size=5) + theme(legend.position = "inside", lege