s.## group2 = names of the protocols further abbreviated.## ASSOC_EXP = whether study was defined as an association or experimental study.## n = number of studies in each group.##    original_name group2    ASSOC_EXP  n## 1            NoR    NoR  ASSOCIATION  6## 2            NoR    NoR EXPERIMENTAL 24## 3            G2D    G2D  ASSOCIATION  1## 4            G2D    G2D EXPERIMENTAL 21## 5            G3T    G3T  ASSOCIATION  2## 6            G3T    G3T EXPERIMENTAL 23## 7          G4_T4    GT4  ASSOCIATION  1## 8          G4_T4    GT4 EXPERIMENTAL  4## 9          G5_T5    GT5 EXPERIMENTAL  3## 10       G6+_T6+   GT6+  ASSOCIATION  6## 11       G6+_T6+   GT6+ EXPERIMENTAL  9## 7.2.  Association versus Experimental studies.tab <- dfassoc %>% group_by(ASSOC_EXP, group2) %>%   summarise(n = sum(n), .groups = "drop") %>%   pivot_wider(names_from  = group2, values_from = n, values_fill = 0) %>%          column_to_rownames("ASSOC_EXP") %>% as.matrix()tab <- tab[, uniquegroup2] tab <- as.data.frame(tab)tab## TABLE S7.T11 (tab). Numbers of association or experimental studies found at each protocol level, re-arranged from S7.S10.## row and column definitions: see S7.T10.##              NoR G2D G3T GT4 GT5 GT6+## ASSOCIATION    6   1   2   1   0    6## EXPERIMENTAL  24  21  23   4   3    9totalnum <- sum(colSums(tab))totalnum## 100rowprops <- signif(prop.table(as.matrix(tab), margin = 1), 3) rowprops## TABLE S7.T12 (tab). Proportions of association or experimental studies found at each protocol level, from S7.T11. ## row and column definitions: see S7.T11.##                NoR    G2D   G3T    GT4    GT5  GT6+## ASSOCIATION  0.375 0.0625 0.125 0.0625 0.0000 0.375## EXPERIMENTAL 0.286 0.2500 0.274 0.0476 0.0357 0.107## 7.3.1.  Fisher's exact test comparing proportions of association/experimental studies across protocol groups - AFTER collapsing columns. newtab <- as.data.frame(tab)newtab$Rep <- newtab$G2D + newtab$G3T + newtab$GT4 + newtab$GT5 + newtab[ , "GT6+"] newtab <- as.data.frame(newtab)newtabnewtab <- newtab[ , -which(names(newtab) %in% c("G2D", "G3T", "GT4", "GT5", "GT6+"))]newtab## TABLE S7.T13 (newtab). Proportions of association or experimental studies found at either NoR or with (batch) replication, from S7.T12. ## column definitions:## NoR = non-replicated.## Rep = replicated.##              NoR Rep## ASSOCIATION    6  10## EXPERIMENTAL  24  60rowtotals <- rowSums(newtab)rowtotalsfisher.newtab <- fisher.test(newtab)fisher.newtab ##     Fisher's Exact Test for Count Data## p-value = 0.5542## 95 percent confidence interval:##  0.3996659 5.1540679## odds ratio ##   1.493614 ## Effect size for association result: Cohen's W. type = "bca" (bias-corrected/accelerated) ### www <- Sys.time()### w <- rcompanion::cohenW(as.matrix(newtab), ci = TRUE, type = "bca", R = 100000)### w### xxx <- Sys.time()### xxx - www### ## Time difference of 47.38133 secs## Cohen w ##   Cohen.w lower.ci upper.ci## 1 0.07143 0.002319    0.244## Fisher's exact p = 0.554; odds ratio 1.49, 95% CI 0.400–5.15; Cohen's w = 0.0714, 95% CI 0.00232–0.244, bias-corrected/accelerated bootstrap, 100000 resamples). ## Cohen W thresholds (Cohen 2013): 0.00 < 0.10 Negligible; 0.10 < 0.30 Small; 0.30 < 0.50 Medium; >0.50 Large - no adjustments to thresholds for 2x2 table. https://peterstatistics.com/Terms/EffectSizes/CohenW.html## Cohen's original benchmarks: 0.1 small, 0.3 medium, 0.5 large ## the point estimate (w = 0.0714) is negligible, below Cohen's small-effect benchmark (0.10), and the upper confidence limit (0.244) remains within the small range, below the medium benchmark (0.30).## No difference detected (from p-value) but underpowered to confirm equivalence.## 7.3.2. Two one-sided z-tests for equivalence test for association/experimental studies.## Chen et al. (2010); Cohen (2013): OR < 1.44 - Very small; 1.44 <= OR < 2.48 - Small; 2.48 <= OR < 4.27 - Medium; OR >= 4.27 - Large. ## Take odds ratio of 2.4 as "small" difference. Needs LOG odds ratio and log se:aa <- newtab[1, 1]bb <- newtab[1, 2]cc <- newtab[2, 1]dd <- newtab[2, 2]logOR <- log((aa*dd)/(bb*cc)) logOR             se    <- sqrt(1/aa + 1/bb + 1/cc + 1/dd) ## =Woolf formula se 				      ## this is already the se of logOR (not OR)margin  <- log(2.4) ## chosen as small.z_upper <- (logOR -  margin) / sez_lower <- (logOR + margin) / sep_upper <- pnorm(z_upper)                  p_lower <- pnorm(z_lower, lower.tail = FALSE)  p_equivalence  <- max(p_upper, p_lower)p_equivalence## 0.2048445## neither difference nor equivalence demonstrable at this sample size## 7.4. Association / experimental graph.cbp2 <- c("#D55E00", "#56B4E9", "#00d99e", "#009E73", "#0072B2", "#5D3A9B", "#CC79A7",  "#000000", "#CC79A7",  "#000000", "#CC79A7") ## color-blind with blackdfassoc$myPattern[dfassoc$ASSOC_EXP == "ASSOCIATION"] <- "stripe"dfassoc$myPattern[dfassoc$ASSOC_EXP == "EXPERIMENTAL"] <- "none"dfassocmyPattern <- dfassoc$myPattern names(myPattern) <- dfassoc$group2 myAngle <- rep(45, 11)names(myAngle) <- dfassoc$group2 ## dev.new(width=10, height=5)## grid::grid.newpage(recording = TRUE) plotProtocolassoc <- ggplot(data = dfassoc, aes(x = group2, y = n, fill = ASSOC_EXP, pattern = ASSOC_EXP)) + geom_bar_pattern(stat = "identity", position = "stack", color = "black", pattern_color = cbp2[1], pattern_fill = "black", pattern_angle = myAngle, pattern = myPattern) +guides(fill = guide_legend(override.aes = list(pattern = myPattern[1:2], pattern_angle = myAngle[1:2], pattern_color = cbp2[1:2], pattern_key_scale_factor = 0.8))) + labs(fill = "") + xlab("Protocol") + ylab("Number of studies") + scale_y_continuous(breaks = c(0, 5, 10, 15, 20, 25, 30), labels = c("0", "5", "10", "15", "20", "25", "30"), expand = c(0, 0), limits = c(0, 35)) + theme(legend.position = "inside", legend.position.inside = c(0.87, 0.85)) dev.new()plotProtocolassocggsave("FigureB_assoc.pdf", plot = plotProtocolassoc, device = "pdf", width = 7, height = 5, units = "in", dpi = 300, path = mypath)## Section 8. Theoretical distributions. 8.1. Coding for no systematic error. 8.2. Plus Uniform systematic error. 8.3. Plus t-distribution systematic error. 8.4. Plus normal distribution systematic error. ## 8.1. Coding for no systematic error.## To find the confidence interval width around a global (combined) mean from several (k) samples of the same size with equal variance (s2). Mean values do not change the CIwidth. ## With equal variances the ratios of CIwidths with two k values is not dependent on s.## parameters for all (including plus systematic errors):conf_level <- 0.95alpha <- 1 - conf_levelk <- c(1, 2, 3, 4) ## number of groupsn <- 100 ## number in each group; larger n decreases differences between k2,k3,k4  (slightly !)s <- 10 ## this is arbitrary ! changes CIwidth but doesn't change ratios of CIwidths ## all groups have this s - this can have different values and will still give the same graph !M <- 10  ## typical group mean - this can have different values and will still give the same graph ! used where systematic errors are addedSE <- s / sqrt(k * n)df <- k * (n - 1) ## for t distributiondist <- "t" ## "normal" or "t" or "log_normal"myquantiles <- function (dist, df = NULL, alpha = 0.05) {if (dist == "normal") {quantiles <- qnorm(1 - alpha/2) }if (dist == "t") {quantiles <- qt(1 - alpha/2, df) }if (dist == "log_normal") {quantiles <- qlnorm(1 - alpha/2) }return(quantiles)}mycrit <- function (dist, df = NULL, alpha = 0.05) {if (dist == "normal") {crit <- qnorm(1 - alpha/2) }if (dist == "t") {crit <- qt(1 - alpha/2, df)}if (dist == "log_normal") {crit <- qlnorm(1 - alpha/2) }return(crit)}vals <- myquantiles(dist = dist, df = df, alpha = 0.05) ## df not used if normalvalsCIwidth_nosys_nonAdj <- 2 * vals * SE## 3.9684 2.7889 2.2724 1.9659CIwidth_nosys <- 100 * (CIwidth_nosys_nonAdj / CIwidth_nosys_nonAdj[[1]]) CIwidth_nosys ## CIwidth_nosys[[1]] / CIwidth_nosys[[2]]## CIwidth_nosys[[2]] / CIwidth_nosys[[3]]## (CIwidth_nosys[[1]] / CIwidth_nosys[[2]]) - (CIwidth_nosys[[2]] / CIwidth_nosys[[3]])## 8.2. Plus Uniform systematic error with range +-% of means (Uniform ±20% and t-distribution ±15% give identical scaled patterns: trivially true for any percentages for k>2). When systematic error scales with 1/k​ (as is realistic in many averaging scenarios), the CI narrows with more groups - The scaled CI width curve will be identical from k >= 2, regardless of whether the underlying distribution is uniform, normal, or log-normal.## Uniform distribution: for ±20% of M:sys_var <- (0.20 * M)^2 / 3  ## The variance of a continuous uniform distribution on [a,b] is known to be ((b−a)^2)/12 [Casella & Berger, 2002]. In the case of a symmetric distribution centered at zero over [−r,r], this simplifies to (r^2)/3.sys_var var_sys_global <- sys_var / k ## it is the 1/k here which gives the curve: note the expected curve here should NOT be Bessel corrected - unlike those from data later on.var_sys_globalvar_sys_global[1] <- 0 ## assumes syst. error cannot be detected for k = 1var_sampling <- s^2 / (k * n)var_sampling # Calculate SE including systematic errorSE_total <- sqrt(var_sampling + var_sys_global)SE_total df_total <- k * (n - 1)vals <- myquantiles(dist = dist, df = df_total, alpha = 0.05) ## df not used if normalvalsCIwidth_1_nonAdj <- 2 * vals * SE_totalCIwidth_1_nonAdj ## Adjust to CIwidth_1[[1]] as 100CIwidth_1 <- 100 * CIwidth_1_nonAdj / CIwidth_1_nonAdj[[1]]CIwidth_1 ## with uniform distribution systematic error# RatiosCIwidth_1[1] / CIwidth_1[2]CIwidth_1[2] / CIwidth_1[3]## 8.3. Plus t-distribution systematic error scaled to % of mean.df_sys <- 10    systematic_scale <- 0.15  ## % of group mean## variance of systematic error (scaled to ±% of mean)sigma_sys <- M * systematic_scale## Var(t_df) = df / (df - 2), for df > 2 ## known variance for t distribution: Johnson et al. 1995.var_sys_per_group <- sigma_sys^2 * (df_sys / (df_sys - 2))## Total variance contribution from systematic error across k groupsvar_sys_global <- var_sys_per_group / kvar_sys_global var_sys_global[1] <- 0 ## assumes syst. error cannot be detected for k = 1var_sampling <- s^2 / (k * n)var_sampling SE_total <- sqrt(var_sampling + var_sys_global)SE_total df <- k * (n - 1)crit <- mycrit(dist, df = df) crit CIwidth_2_nonAdj <- 2 * crit * SE_totalCIwidth_2_nonAdj ## Adjust to CIwidth_2_nonAdj[[1]] as 100:CIwidth_2 <- 100 * CIwidth_2_nonAdj / CIwidth_2_nonAdj[[1]]CIwidth_2 ## with t distribution systematic errorCIwidth_2[1] / CIwidth_2[2]CIwidth_2[2] / CIwidth_2[3]CIwidth_1[1] / CIwidth_1[2]CIwidth_1[2] / CIwidth_1[3]## 8.4. Plus normal distribution systematic error scaled to % of mean.systematic_scale <- 0.15  ## Variance of systematic error (scaled to ±% of mean)sigma_sys <- M * systematic_scalevar_sys_per_group <- sigma_sys^2 # Total variance contribution from systematic error across k groupsvar_sys_global <- var_sys_per_group / kvar_sys_global var_sys_global[1] <- 0 ## assumes syst. error cannot be detected for k = 1var_sampling <- s^2 / (k * n)var_sampling SE_total <- sqrt(var_sampling + var_sys_global)SE_total df_total <- k * (n - 1)crit <- mycrit(dist, df = df_total) critCIwidth_3_nonAdj <- 2 * crit * SE_totalCIwidth_3_nonAdj ## Adjust to CIwidth_3_nonAdj[[1]] as 100:CIwidth_3 <- 100 * CIwidth_3_nonAdj / CIwidth_3_nonAdj[[1]]CIwidth_3 ## with normal distribution systematic error## For text - using only nosys values relative to k = 2 NOT k = 1 !!nosysRelk2 <- 100 * CIwidth_nosys_nonAdj / CIwidth_nosys_nonAdj[[2]] ## [2] !nosysRelk2diff1_nosys <- nosysRelk2[1] - nosysRelk2[2]diff2_nosys <- nosysRelk2[2] - nosysRelk2[3]diff3_nosys <- nosysRelk2[3] - nosysRelk2[4]diffs_nosys <- c(diff1_nosys, diff2_nosys, diff3_nosys) diffs_nosys ##  42.29623 18.51736 10.98871## for comparison - not put onto graph:uniRelk2 <- 100 * CIwidth_1_nonAdj / CIwidth_1_nonAdj[[2]] ## [2] !uniRelk2diff1_uni <- uniRelk2[1] - uniRelk2[2]diff2_uni <- uniRelk2[2] - uniRelk2[3]diff3_uni <- uniRelk2[3] - uniRelk2[4]diffs_uni <- c(diff1_uni, diff2_uni, diff3_uni) diffs_uni ## −6.8452 18.517364 10.988709 ## note that for k ≥ 2 the scaled shape is independent of the systematic variancettRelk2 <- 100 * CIwidth_2_nonAdj / CIwidth_2_nonAdj[[2]] ## [2] !ttRelk2diff1_tt <- ttRelk2[1] - ttRelk2[2]diff2_tt <- ttRelk2[2] - ttRelk2[3]diff3_tt <- ttRelk2[3] - ttRelk2[4]diffs_tt <- c(diff1_tt, diff2_tt, diff3_tt) diffs_tt ## -27.12334  18.51736  10.98871normRelk2 <- 100 * CIwidth_3_nonAdj / CIwidth_3_nonAdj[[2]] ## [2] !normRelk2diff1_norm <- normRelk2[1] - normRelk2[2]diff2_norm <- normRelk2[2] - normRelk2[3]diff3_norm <- normRelk2[3] - normRelk2[4]diffs_norm <- c(diff1_norm, diff2_norm, diff3_norm) diffs_norm ##  -21.06825  18.51736  10.98871percinc1 <- paste0(round(diff1_nosys, 1), "%")percinc1percinc2 <- paste0(round(diff2_nosys, 1), "%")percinc2percinc3 <- paste0(round(diff3_nosys, 1), "%")percinc3CIwidth_1 <- c(CIwidth_1) ## with uniform distribution systematic errorCIwidth_2 <- c(CIwidth_2) ## with t distribution systematic errorCIwidth_3 <- c(CIwidth_3) ## with normal distribution systematic errorxxx <- c("NoR", "D", "T", "T4")xxx <- factor(xxx, levels = c("NoR", "D", "T", "T4"))dfCI <- data.frame(xxx, CIwidth_nosys, CIwidth_1, CIwidth_2, CIwidth_3)colnames(dfCI) <- c("Protocol", "CIwidth_nosys", "CIwidth_1", "CIwidth_2", "CIwidth_3")cbp2 <- c("#D55E00", "#56B4E9", "#009E73", "#E69F00", "#F0E442", "#0072B2", "#CC79A7",  "#000000") mylabels <- c("No SysErr", "Uniform", "Normal", "t")mylabels <- factor(mylabels, levels = c("No SysErr", "Uniform", "Normal", "t"))ybreaks <- c(0, 50, 100, 140)ylabels <- paste0(ybreaks)ylabelsannotation1 <- data.frame(x = c(1.7, 2.4, 3.4), y = c(109, 102, 85), label = c("a", perc