f_sys <- 30    ## degrees of freedom for t-distributionsystematic_scale <- 0.10  ## 10% of group mean## Variance of systematic error (scaled to ±10% of mean)sigma_sys <- M * systematic_scale## Var(t_df) = df / (df - 2), for df > 2var_sys_per_group <- sigma_sys^2 * (df_sys / (df_sys - 2))var_sys_global <- var_sys_per_group / kvar_sys_global var_sampling <- s^2 / (kdf * ndf)head(var_sampling, 100)SE_total <- var_sampling for (i in 1:nrow(SE_total)) {SE_total[i, ] <- sqrt(var_sampling[i, ] + var_sys_global)}head(SE_total) df_total <- kdf * (ndf - 1)head(df_total)crit <- df_total; ## temp for structurefor (i in 1:ncol(df_total)) {for (j in 1:nrow(df_total)) {crit[j, i] <- qt(1 - alpha/2, df_total[j, i])}}head(crit)CIwidth_n_nonAdj <- 2 * crit * SE_totalhead(CIwidth_n_nonAdj)## Adjust to CIwidth_n_nonAdj[ , 1] as 100:CIwidth_n <- CIwidth_n_nonAdj for (i in 1:ncol(CIwidth_n)) {CIwidth_n[ , i] <- CIwidth_n_nonAdj[ , i] / CIwidth_n_nonAdj[ , 1] }head(CIwidth_n)CIwidth_n <- CIwidth_n * 100head(CIwidth_n)CIwidth_n <- as.data.frame(t(CIwidth_n))colnames(CIwidth_n) <- nCIwidth_n <- cbind(k, CIwidth_n)head(CIwidth_n)n_char <- as.character(n)n_char <- factor(n_char, levels = unique(n_char))mylabels <- paste0(n_char)mylabels[6] <- "10000 or normal"dev.new()plotCInA <- ggplot(data = CIwidth_n)  +     geom_point(aes(x = k, CIwidth_n[ , 2], color = n_char[[1]]), size  = 3, shape = 1) +geom_point(aes(x = k, y = CIwidth_n[ , 3], color = n_char[[2]]), size  = 6, shape = 3) +geom_point(aes(x = k, y = CIwidth_n[ , 4], color = n_char[[3]]), size  = 4, shape = 17) +geom_point(aes(x = k, y = CIwidth_n[ , 5], color = n_char[[4]]), size  = 4, shape = 4) +geom_point(aes(x = k, y = CIwidth_n[ , 6], color = n_char[[5]]), size  = 4, shape = 18) +geom_point(aes(x = k, y = CIwidth_n[ , 7], color = n_char[[6]]), size  = 4, shape = 6) + geom_line(aes(x = k, y = CIwidth_n[ , 2], color = n_char[[1]])) +geom_line(aes(x = k, y = CIwidth_n[ , 3], color = n_char[[2]])) +geom_line(aes(x = k, y = CIwidth_n[ , 4], color = n_char[[3]])) +geom_line(aes(x = k, y = CIwidth_n[ , 5], color = n_char[[4]])) +geom_line(aes(x = k, y = CIwidth_n[ , 6], color = n_char[[5]])) +geom_line(aes(x = k, y = CIwidth_n[ , 7], color = n_char[[6]])) + scale_x_continuous(breaks = c(2, 3, 4), labels = c("2", "3", "4"), expand = c(0, 0), limits = c(1.8, 4.2)) + scale_y_continuous(breaks = c(0, 20, 40, 60, 80, 100), labels = c("0", "20", "40", "60", "80", "100"), expand = c(0, 0), limits = c(0, 105)) + ylab("Relative C.I. width (%)") + xlab("Number of replicates") + scale_colour_manual(name = "Sample size, one rep", values = c(cbp2[1], cbp2[8], cbp2[7], cbp2[6], cbp2[5], cbp2[4]), limits = c(n_char[[1]], n_char[[2]], n_char[[3]], n_char[[4]], n_char[[5]], n_char[[6]]), labels = mylabels) + theme(legend.title = element_text(family = "serif"), legend.position = "inside", legend.position.inside = c(0.29, 0.27), legend.box.background = element_rect(colour = "black")) ## Add label to plot:plotCIn <- cowplot::ggdraw(plotCInA) + draw_figure_label(label = "a.", position = c("top.left"), size = 25, fontface = "bold")plot(plotCIn)ggsave("FigureE_CIn.pdf", plot = plotCIn, device = "pdf", width = 6, height = 6, units = "in", dpi = 300, path = mypath)##________________________________________________________## Section 11. Graph of Gain (= relative change in confidence-interval width) as sample size N increases, with t-distribution systematic error.conf_level <- 0.95 alpha <- 1 - conf_levelk <- c(2, 3, 4)n <- seq(from = 5, to = 335, by  = 5)kdf <- data.frame(matrix(k, ncol = length(k), nrow = length(n), byrow = TRUE))head(kdf)ndf <- kdffor (i in 1:length(k)) {ndf[ , i] <- n}colnames(ndf) <- kcolnames(kdf) <- khead(ndf)head(kdf)s <- 50 ## all groups have this s - this can have different values and will still give the same graph !M <- 10  ## typical group mean - this can have different values and will still give the same graph !df_sys <- 30    # degrees of freedom for t-distributionsystematic_scale <- 0.10  # 10% of group mean## Variance of systematic error (scaled to ±10% of mean)sigma_sys <- M * systematic_scale## Var(t_df) = df / (df - 2), for df > 2var_sys_per_group <- sigma_sys^2 * (df_sys / (df_sys - 2))var_sys_global <- var_sys_per_group / kvar_sys_global var_sampling <- s^2 / (kdf * ndf)head(var_sampling, 100)SE_total <- var_sampling for (i in 1:nrow(SE_total)) {SE_total[i, ] <- sqrt(var_sampling[i, ] + var_sys_global)}head(SE_total) df_total <- kdf * (ndf - 1)head(df_total)crit <- df_total; for (i in 1:ncol(df_total)) {for (j in 1:nrow(df_total)) {crit[j, i] <- qt(1 - alpha/2, df_total[j, i])}}head(crit)CIwidth_ng_nonAdj <- 2 * crit * SE_totalhead(CIwidth_ng_nonAdj)## Adjust to CIwidth_ng_nonAdj[ , 1] as 100:CIwidth_ng <- CIwidth_ng_nonAdj for (i in 1:ncol(CIwidth_ng)) {CIwidth_ng[ , i] <- CIwidth_ng_nonAdj[ , i] / CIwidth_ng_nonAdj[ , 1] }head(CIwidth_ng)CIwidth_ng$diff1 <- 100 * (CIwidth_ng[ , 1] - CIwidth_ng[ , 2])CIwidth_ng$diff2 <- 100 * (CIwidth_ng[ , 2] - CIwidth_ng[ , 3])CIwidth_ng$Gain <- 100 * (CIwidth_ng$diff1 - CIwidth_ng$diff2) / CIwidth_ng$diff2CIwidth_ng$n <- nhead(CIwidth_ng)class(CIwidth_ng)nrow(CIwidth_ng)ncol(CIwidth_ng)dev.new()plotGainA <- ggplot(data = CIwidth_ng)  +     geom_line(aes(x = n, y = Gain)) + scale_y_continuous(breaks = c(0, 10, 30, 50, 70, 90, 100), labels = c("0", "10", "30", "50", "70", "90", "100"), expand = c(0, 0), limits = c(0, 100)) + ylab("Gain (%)") + xlab("Sample size (n) per replicate") + coord_cartesian(xlim = c(0, 300), clip = 'off') plotGainAplotGain <- cowplot::ggdraw(plotGainA) + draw_figure_label(label = "b.", position = c("top.left"), size = 25, fontface = "bold")plotGainggsave("FigureF_Gain.pdf", plot = plotGain, device = "pdf", width = 6, height = 6, units = "in", dpi = 300, path = mypath)mymin <- CIwidth_ng[CIwidth_ng$Gain == min(CIwidth_ng$Gain), ]mymin 