d three times - but representative results shown.## SE for combining results is sp / sqrt(n * k) ## SE is NOT sp / sqrt(n/k) = sp * sqrt(k/n) which would be for analyzing differences ## The degrees of freedom for unequal variances were estimated with or without the Welch–Satterthwaite approximation (see: International Organization for Standardization: ISO Guide to the Expression of Uncertainty in Measurement) and references (given at end of file): Ballico (2000); Welch (1947).## 12.1. First part assumes NO SYSTEMATIC ERRORS FROM DATA:## means = original means from data## ss = either original SDs or original SEs from data (depending on s_method)## s_method = method to use either SDs or SEs from original data## ns = list of sample sizes from original data (usually all the same number)## alpha = significance p-value cut-off## Welch = Welch-Satterthwaite adjustmentglobal_mean_CI_nosys <- function(means, ss, s_method = c("sd", "SE"), ns, alpha = 0.05, Welch = FALSE) {  s_method <- match.arg(s_method)  k <- length(means)  total_n <- sum(ns)  weights <- ns / total_nglobal_mean <- sum(weights * means)  if (s_method == "sd") {sds <- ssvar_total <- sum((sds^2 / ns) * (weights^2))var_i <- (weights^2 * sds^2) / ns  } else if (s_method == "SE") {SE <- ssvar_total <- sum((weights^2) * (SE^2))var_i <- (weights^2 * SE^2)}SE_total <- sqrt(var_total)if (Welch == TRUE) {df_num <- var_total^2df_den <- sum(var_i^2 / (ns - 1)) ## Welch–Satterthwaite df correction - differing variancesdf <- df_num / df_den} else {df <- sum(ns - 1)} t_crit <- qt(p = (1 - alpha/2), df)CI_lower <- global_mean - t_crit * SE_totalCI_upper <- global_mean + t_crit * SE_totalCIwidth <- 2*t_crit * SE_totalExpCIwidth <- 2*qt((1-alpha/2), df = sum(ns-1)) / sqrt(sum(ns)) ## sample sizes across k are allowed to differ using sqrt(sum(ns)) rather than sqrt(k)return(c(CIwidth = CIwidth, ExpCIwidth = ExpCIwidth))}## 12.1 Raw data:## 12.1 A. Tonk et al. (2017) Fig 1. (a) top panel Landraces TR1 to TR7. See Supplemental_file_S8 for reference and details of data extraction.Tonk_label <- c("TR1", "TR2", "TR3", "TR4", "TR5", "TR6", "TR7")Tonk_mean <- c(34, 52, 46, 56, 39, 49, 23.5)Tonk_sd <- c(8.75, 15.25, 12.5, 25, 10.75, 15.25, 4.5)Tonk_n <- c(100, 100, 100, 100, 100, 100, 100)Tonk_k <- 1:7Tonk_raw_df <- data.frame(Tonk_label, Tonk_k, Tonk_mean, Tonk_sd, Tonk_n) Tonk_raw_df colnames(Tonk_raw_df) <- c("label", "k", "mean", "sd", "n")Tonk_raw_df ## 12.1 B. Kichigina et al. (2017) Fig 5(a) - Al sensitive genotypesKich_label <- c("8473", "3654", "2759", "1903")Kich_mean <- c(3.9, 2.4, 1.4, 7)Kich_SE <- c(1.1, 0.35, 0.15, 1.1)Kich_n <- c(5, 5, 5, 5)Kich_k <- 1:4Kich_raw_df <- data.frame(Kich_label, Kich_k, Kich_mean, Kich_SE, Kich_n) Kich_raw_df colnames(Kich_raw_df) <- c("label", "k", "mean", "SE", "n")Kich_raw_df ## 12.1 C. Carlucci et al. (2017) Table 5 Ilyonectria liriodendriCarl_label <- c("BF144", "BF47", "BF12")Carl_mean <- c(8.2, 10.8, 11.8)Carl_sd <- c(3.1, 1.1, 1.9)Carl_n <- c(10, 10, 10)Carl_k <- 1:3Carl_raw_df <- data.frame(Carl_label, Carl_k, Carl_mean, Carl_sd, Carl_n) Carl_raw_df colnames(Carl_raw_df) <- c("label", "k", "mean", "sd", "n")Carl_raw_df ## N is a guess, but the patterns of relative C.I. do not change substantially from N=3 to N=10000 in terms of Actual being above Expected for k=1 (both are shifted upwards at very low N and only at N=2 does Expected exceed Actual; or downwards slightly for N=10000).## 12.1 D. Lawrence et al. (2017) - FIG 1 NATIVELawr_label <- c("Gardener Marsh", "Pheasant Branch Slough", "Prairie Wolf")Lawr_mean <- c(6.2, 5.3, 14.2)Lawr_SE <- c(2.1, 3, 3.9)Lawr_n <- c(5, 5, 5)Lawr_k <- 1:3Lawr_raw_df <- data.frame(Lawr_label, Lawr_k, Lawr_mean, Lawr_SE, Lawr_n) Lawr_raw_df colnames(Lawr_raw_df) <- c("label", "k", "mean", "SE", "n")Lawr_raw_df ## 12.1 E. Zhang et al. (2017) Fig 8 A ControlZhan_label <- c("Merlot", "Syrah", "Concord")Zhan_mean <- c(20, 23.5, 27.2)Zhan_SE <- c(1, 1, 1.4)Zhan_n <- c(10, 10, 10)Zhan_k <- 1:3Zhan_raw_df <- data.frame(Zhan_label, Zhan_k, Zhan_mean, Zhan_SE, Zhan_n) Zhan_raw_df colnames(Zhan_raw_df) <- c("label", "k", "mean", "SE", "n")Zhan_raw_df ## 12.1 F. Driver et al. (2017) Fig 9B, Total PA, High PDriv_label <- c("GPD3-OE1", "GPD3-OE2", "GPD3-OE3")Driv_mean <- c(1.8, 2.6, 3)Driv_SE <- c(0.4, 0.6, 1.3)Driv_n <- c(3, 3, 3)Driv_k <- 1:3Driv_raw_df <- data.frame(Driv_label, Driv_k, Driv_mean, Driv_SE, Driv_n) Driv_raw_df colnames(Driv_raw_df) <- c("label", "k", "mean", "SE", "n")Driv_raw_df ## 12.1 G. Zhou et al. (2017) Fig 3A Relative transcription level## Note: this data extraction is chosen for its k-group structure and is independent of the protocol classification.Zhou_label <- c("RG2", "RG6", "RG14", "RG20")Zhou_mean <- c(0.8, 0.9, 0.8, 2.1)Zhou_sd <- c(0.3, 0.35, 0.5, 0.5)Zhou_n <- c(3, 3, 3, 3)Zhou_k <- 1:4Zhou_raw_df <- data.frame(Zhou_label, Zhou_k, Zhou_mean, Zhou_sd, Zhou_n) Zhou_raw_df colnames(Zhou_raw_df) <- c("label", "k", "mean", "sd", "n")Zhou_raw_df ## 12.1 H. Clark et al. Growth rates of Pseudocercosporella herpotrichoides.Clark_label <- c("R89/1", "R89/4", "R90/6", "R91/7")Clark_mean <- c(18.5, 19.3, 17.8, 20)Clark_sd <- c(0.577, 0.500, 0.957, 0.816)Clark_n <- c(4, 4, 4, 4)Clark_k <- 1:4Clark_raw_df <- data.frame(Clark_label, Clark_k, Clark_mean, Clark_sd, Clark_n) Clark_raw_df colnames(Clark_raw_df) <- c("label", "k", "mean", "sd", "n")Clark_raw_df ## 12.1.1 Creation of CI ratio dataframes from raw dataframes; C.I. width ratios relative to k = 2.raw_df_list <- list(Tonk = Tonk_raw_df, Kich = Kich_raw_df, Carl = Carl_raw_df, Lawr = Lawr_raw_df, Zhan = Zhan_raw_df, Driv = Driv_raw_df, Zhou = Zhou_raw_df, Clark = Clark_raw_df)raw_df_list myprefix <- names(raw_df_list)myprefixCIdf_list <- list(); for (i in 1:length(raw_df_list)) {raw_df <- raw_df_list[[i]]s_method <- intersect(c("sd", "SE"), colnames(raw_df)) ss <- raw_df[[s_method]]kk <- raw_df$kCIdata_WelchNO <- list(); CIdata_WelchYES <- list(); for (j in 1:nrow(raw_df)) {CIdata_WelchNO[[j]] <- global_mean_CI_nosys(means = raw_df$mean[1:j], ss = ss[1:j], s_method = s_method, ns = raw_df$n[1:j], Welch = FALSE)CIdata_WelchYES[[j]] <- global_mean_CI_nosys(means = raw_df$mean[1:j], ss = ss[1:j], s_method = s_method, ns = raw_df$n[1:j], Welch = TRUE)}CIdf_NoW <- as.data.frame(list.rbind(CIdata_WelchNO))CIdf_W <- as.data.frame(list.rbind(CIdata_WelchYES))actual_ratio_NoW <- 100 * signif(CIdf_NoW$CIwidth / CIdf_NoW[2, "CIwidth"], 4) actual_ratio_W <- 100 * signif(CIdf_W$CIwidth / CIdf_W[2, "CIwidth"], 4) expected_ratio <- 100 * signif(CIdf_NoW$ExpCIwidth / CIdf_NoW[2, "ExpCIwidth"], 4) mydf <- data.frame(kk, actual_ratio_NoW, actual_ratio_W, expected_ratio)colnames(mydf) <- c("k", paste0(myprefix[i], "_Act_NoW"), paste0(myprefix[i], "_Act_W"), paste0(myprefix[i], "_Exp"))CIdf_list[[i]] <- mydf}names(CIdf_list) <- myprefix## All Real data:CIdf_list## TABLE S7.T14. (CIdf_list). Actual and expected 95% confidence interval widths, from sampling error alone as ratios of that at k=2, from function global_mean_CI_nosys. ## column definitions:## k = number of replicates included for this row's data## _Act_NoW = actual ratio of confidence interval width (sampling error only) relative to that at k=2. CIwidth = 2*t_crit*SE_total, where SE_total = sqrt(var_total), var_total = sum((weights^2) * (sds^2 / ns)) for studies supplying SDs or sum((weights^2) * (SE^2)) for studies supplying SEs, and weights = ns/total_n. Degrees of freedom for t_crit are pooled, df = sum(ns-1); no Welch's adjustment. ## _Act_W = as _Act_NoW, but with Welch–Satterthwaite adjustment.## _Exp = expected ratio of confidence interval width (sampling error only) relative to that at k=2. ExpCIwidth = 2*qt((1-alpha/2), df = sum(ns-1)) / sqrt(sum(ns)). This always uses the pooled df and is therefore unaffected by the Welch setting.## NOTE: Percentages 