tch.arg(s_method)    k <- length(means)  total_n <- sum(ns)  weights <- ns / total_n  global_mean <- sum(weights * means)  if (s_method == "sd") {sds <- ssvar_sampling <- sum((sds^2 / ns) * (weights^2))var_i <- (weights^2 * sds^2) / ns  } else if (s_method == "SE") {SE <- ssvar_sampling <- sum((weights^2) * (SE^2))var_i <- (weights^2 * SE^2)} if (sys_method == "var") {  if (k > 1) {    var_sys <- sum((means - global_mean)^2) / (k*(k - 1))  ## NOTE: this is the standard error of the grand mean estimated from the variance among the means, with Bessel's correction used for actual data  } else {    var_sys <- 0  }} else if (sys_method == "range") {  delta <- max(means) - min(means)  var_sys <- (delta / 2)^2 / k ## NOTE this range estimate of var_sys is crude, probably needs further adjustments for precision use, and was not used further in this article.}  var_total <- var_sampling + var_sys  SE_total <- sqrt(var_total)if (Welch == TRUE) {  df_samp <- var_sampling^2 / sum((var_i^2) / (ns - 1))   ## Welch's adjustment if (var_sys > 0) { ## Welch–Satterthwaite also adjusts df for t_crit from var_sys:  df <- (var_sampling + var_sys)^2 / ((var_sampling^2 / df_samp) + (var_sys^2 / (k - 1)))} else {  df <- df_samp} ## from if (var_sys } else {  df <- sum(ns - 1)   ## no Welch's: equal underlying variances assumed; pooled df. ## This is the same df as used for ExpCIwidth, so t_crit cancels in the ratio.} ## from if (Welch t_crit <- qt(1 - alpha / 2, df)   CI_lower <- global_mean - t_crit * SE_total  CI_upper <- global_mean + t_crit * SE_total  CI_sys_width <- 2*t_crit * SE_total  ExpCIwidth <- 2*qt((1-alpha/2), df = sum(ns-1)) / sqrt(sum(ns))return(c(CI_sys_width = CI_sys_width, ExpCIwidth = ExpCIwidth, var_sampling = var_sampling, var_sys = var_sys))}## 12.2.1. Creation of systematic-error dataframes from raw dataframes.CIdfsysvar_list <- list(); CIdfsysvarMeans_list <- list(); ratiosys_sampl <- vector(); for (i in 1:length(raw_df