e = "Ratio", values = c("Actualsys" = "dotted", "Actual" = "dashed", "Expected" = "solid")) + theme(axis.title.x = element_text(vjust = -2)) + geom_line(aes(x = k, y = Exp, color = "Expected", linetype = "Expected")) +geom_text(data = annotation1, aes(x = x, y = y, label = label), color = cbp2[8], size = 5, fontface = "bold") + theme(legend.position = "none")  {if (show_ylab[i] == FALSE) {ttt <- ttt + theme(axis.title.y = element_blank())}}plot_listsys[[i]] <- ttt}names(plot_listsys) <- myprefixfor (i in 1:length(plot_listsys)) {dev.new()print(plot_listsys[[i]])if (grW == TRUE) {grnameH <- paste0("FigureH_", myprefix[i], "_real_W.pdf")} else {grnameH <- paste0("FigureH_", myprefix[i], "_real_NoW.pdf")}ggsave(grnameH, plot = plot_listsys[[i]], device = "pdf", width = 6, height = 7, units = "in", dpi = 300, path = mypath)}## TABLE S7.T17. (CIdf_listsys). Actual and expected 95% confidence interval widths, from sampling error plus systematic errors (with actual from sampling error alone for comparison), as percentages of the corresponding width at k=2, from function global_mean_CI_sys. ## column definitions:## k = number of replicates included for this row's data## _Actsysvar_NoW = confidence interval width including systematic and sampling error, as a percentage of the same quantity at k=2. CI_sys_width = 2*t_crit * SE_total, where SE_total = sqrt(var_sampling + var_sys), see S7.T15. No Welch-Satterthwaite adjustment.## _Actsysvar_W = as _Actsysvar_NoW, but with Welch–Satterthwaite adjustment.## _Exp = expected ratio of confidence interval width (sampling error only) relative to that at k=2. ExpCIwidth = 2*qt((1-alpha/2), df = sum(ns-1)) / sqrt(sum(ns)). This always uses the pooled df and is therefore unaffected by the Welch setting.## _Act_NoW = actual ratio of confidence interval width (sampling error only) relative to that at k=2. CIwidth = 2*t_crit*SE_total, where SE_total = sqrt(var_total), var_total = sum((weights^2) * (sds^2 / ns)) f